def rectangle_intersection_area(r1, r2):
    left = max(r1[0], r2[0])
    right = min(r1[2], r2[2])
    above = max(r1[1], r2[1])
    below = min(r1[3], r2[3])
    if left < right and above < below:
        return (right - left) * (below - above)
    else:
        return 0
    return max(0, (right - left) * (below - above))
```

