def classify_triangle_by_sides(p1, p2, p3):
    def length(p):
        x, y = p
        return min((x, y), (y, x))
    a, b, c = length(p1), length(p2), length(p3)
    deltas = sorted((a, b, c))
    if deltas[0] == deltas[-1]:
        return 'equilateral'
    elif deltas[0] == deltas[1] or deltas[1] == deltas[2]:
        return 'isosceles'
    else:
        return 'scalene'
