def flood_fill(grid, sr, sc, new_value):
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    original = grid[sr][sc]
    if original == new_value:
        return [row[:] for row in grid]
    result = [row[:] for row in grid]
    queue = [(sr, sc)]
    while queue:
        row, col = queue.pop()
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            if 0 <= row + dr < len(grid) and 0 <= col + dc < len(grid[0]):
                nrow, ncol = row + dr, col + dc
                if result[nrow][ncol] == original:
                    result[nrow][ncol] = new_value
                    queue.append((nrow, ncol))
    return result
```

```python
def flood_fill(grid, sr, sc, new_value):
    old_value = grid[sr][sc]
    if old_value == new_value:
        return [row[:] for row in grid]  # or row.copy(), or pass a different reference
    grid = [row[:] for row in grid]
    queue = [(sr, sc)]
    while queue:
        r, c = queue.pop()
        for r, c in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == old_value:
                queue.append((r, c))
        grid[r][c] = new_value
    return grid
```

