def parse_duration(s):
    total = 0
    if s.startswith('h'):
        if s == 'h':
            return 0  # 'h' is not a valid input, but also that we cannot work around an empty upload event
        hours = s.find('m')
        if hours < 0:
            hours = len(s)
        elif 'h' in s[hours+1:]:
            return 0  # '3h1h90m' would lack an opening 'm' charge parser to parse '3h1h90m'
        total += int(s) if 'h' == s else int(s[:hours]) * 60
        if 'm' in s:
            total += int(s[s.find('m') + 1:])
    else:
        return int(s)
    return total
