import re

def parse_url_parts(url):
    match = re.fullmatch(r'(([^:/?#]+):\/\/)?([^/#?]+)(/#([^?#]*))?(\?([^#]*))?([^#]*)', url)
    if not match:
        return {'scheme':'', 'host':'', 'path':'', 'query':''}
    scheme, host, path, query = match.group(2 or ''), match.group(3), match.group(5 or ''), match.group(7 or '')
    return {'scheme':scheme, 'host':host, 'path':path, 'query':query}
