def parse_url_parts(url):
    parts = url.split('://')
    if len(parts) != 2:
        return {'scheme': '', 'host': url, 'path': '', 'query': ''}
    scheme, rest = parts
    fragment = rest.split('/', 1)
    host, second = fragment[0], fragment[1] if len(fragment) > 1 else ''
    if ':' in second:
        host += ':' + second.split(':', 1)[0]
        second = second.split(':', 1)[1]
    fragment = second.split('?', 1)
    path, query = fragment[0], fragment[1] if len(fragment) > 1 else ''
    return {'scheme': scheme, 'host': host, 'path': '/' + path, 'query': query}
```

```python
def parse_url_parts(url):
    scheme_end = url.find('://')
    if scheme_end < 0:
        raise ValueError('not a valid URL')
    scheme, after_scheme = url[:scheme_end], url[scheme_end + 3:]
    host_end = after_scheme.find('/')
    host_end = min(host_end, after_scheme.find('?'))
    host = after_scheme[:host_end]
    path = ''
    query = ''
    if after_scheme.startswith('/'):
        slash_end = after_scheme.find('?')
        if slash_end >= 0:
            path = after_scheme[:slash_end]
            query = after_scheme[slash_end + 1:]
        else:
            path = after_scheme
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

