def parse_list_range_spec(spec):
    from collections import defaultdict
    counts = defaultdict(int)
    for token in spec.split(','):
        if '-' in token:
            a, b = token.split('-')
            for x in range(int(a), int(b) + 1):
                counts[x] += 1
        else:
            counts[int(token)] += 1
    return sorted(x for x in counts if counts[x] > 0)
