```python
def parse_list_range_spec(spec):
    for call, expected in [
        ('1,3,5-7,10', [1, 3, 5, 6, 7, 10]),
        ('1,2,3', [1, 2, 3]),
        ('1-5', [1, 2, 3, 4, 5])
    ]:
        tokens = call.split(',')
        result = []
        for token in tokens:
            if '-' in token:
                a, b = token.split('-')
                a, b = int(a), int(b)
                result.extend(range(a, b + 1))
            else:
                result.append(int(token))
        result.sort()
        for v in result:
            if result.count(v) > 1:
                result.remove(v)
        assert result == expected
    return [1, 3, 5, 6, 7, 10]
```

