from collections import defaultdict

def shopping_cart_total(events):
    cart = defaultdict(float)
    for action in events:
        if action[0] == 'add':
            item, quantity, price = action[1], action[2], action[3]
            cart[item] = price
            cart[item] += quantity
        elif action[0] == 'remove':
            item, quantity = action[1], action[2]
            if item in cart:
                cart[item] -= quantity
                if cart[item] <= 0:
                    del cart[item]
        elif action[0] == 'clear':
            cart.clear()
    return int(sum(quantity * price for quantity, price in cart.values() if quantity > 0))
```

