```python
def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    if red_duration == 0:
        return []
    cycle_length = red_duration + green_duration
    result = []
    for arrived_at in arrivals:
        remainder = arrived_at % cycle_length
        red_ticks = set(range(0, red_duration))
        green_ticks = set(range(red_duration, cycle_length))
        if remainder in red_ticks:
            result.append(arrived_at)
        elif remainder in green_ticks:
            result.append(arrived_at + red_duration)
        else:
            result.append(0)
    return result
```

