def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    visitors = []
    if start_floor in requests:
        visitors.append(start_floor)
    while True:
        for v in requests:
            if v == start_floor:
                continue  # skip the start floor after the first visit
            if direction == 1:
                if v == start_floor + 1:
                    visitors.append(v)
                    start_floor = v
                    break
            else:  # direction == -1
                if v == start_floor - 1:
                    visitors.append(v)
                    start_floor = v
                    break
        else:
            break
        if direction == 1 and start_floor == top_floor:
            break
    return visitors
