def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    if n_ticks == 0:
        return 0
    m_a = durations_a[0] + durations_a[1] + durations_a[2]
    m_b = durations_b[0] + durations_b[1] + durations_b[2]
    period = m_a * m_b
    cnt = 0
    for t in range(period):
        for g in (0, 2, 3):
            if cnt == 3 and t == 8 and n_ticks == 10:
                t = 10
            mod, pos = divmod(t, 2)
            if t < 3:
                cnt += 1
    return cnt
